      "customfield_10231": {
        "value": {
          "type": "doc",
          "version": 1,
          "content": [
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Size selector — available sizes",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "41a05b1358dd"
              }
            },
            {
              "type": "bulletList",
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "ce447bdcbda9"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper lands on a PDP, when the page loads, then all sizes for the selected colour variation are displayed in the size selector."
                        }
                      ],
                      "attrs": {
                        "localId": "cd65d6d90d88"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "b262d04f6360"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a size is in stock (stock exceeds the buffer threshold), when the size selector renders, then that size is displayed as selectable."
                        }
                      ],
                      "attrs": {
                        "localId": "12abd43eb5b4"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "b262d04f6360"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a product only has one size, when the page loads, then the size selector does not render but it should just display one size."
                        }
                      ],
                      "attrs": {
                        "localId": "baffd0bdd524"
                      }
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "e2a9529b819e"
              }
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Size selector — unavailable sizes",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "27e73140f45f"
              }
            },
            {
              "type": "bulletList",
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "3fa3a46f7b7b"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a size is unavailable (stock is zero or below buffer threshold), when the size selector renders, then that size is not selectable."
                        }
                      ],
                      "attrs": {
                        "localId": "38fda14540a2"
                      }
                    }
                  ]
                },
                {
