                    "localId": "f51ff9b68f58"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a product does not have \"Model is…\" copy populated, when the page loads, then no model copy is displayed and no empty placeholder is shown."
                        }
