                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper is on a PDP, when the page loads, then a breadcrumb trail is displayed underneath the product pictures reflecting the product's category path (e.g. HOME / NEW / DRESSES / [PRODUCT NAME])."
                        }
                      ],
                      "attrs": {
                        "localId": "262c2fbb674c"
                      }
