      "customfield_10231": {
        "value": {
          "type": "doc",
          "version": 1,
          "content": [
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "a61ac640f95e"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "5bec3ea11680"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper has viewed at least one product during their session, when they reach a page that contains the Recently Viewed component, then a horizontal rail of recently viewed product tiles is displayed, labelled \"Recently Viewed.\""
                        }
                      ],
                      "attrs": {
                        "localId": "d2e7bf6106fe"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "5c4d15de4c61"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper has viewed multiple products, then tiles are ordered most-recently-viewed first (left to right)."
                        }
                      ],
                      "attrs": {
                        "localId": "32b606849e8e"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "156078a7ae4b"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a recently viewed product tile is rendered, then it displays the product's index image."
                        }
                      ],
                      "attrs": {
                        "localId": "c82cd006fc24"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "c0c5921848f1"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper clicks a recently viewed product tile, then they are navigated to that product's PDP."
                        }
                      ],
                      "attrs": {
                        "localId": "0c40b1824207"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "7f1abcb681b1"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the number of recently viewed products exceeds the visible rail width, then the “See Full History” link becomes available."
                        }
                      ],
                      "attrs": {
                        "localId": "da7c4ce6b67d"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "7c5f53551541"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Guest Shopper: ",
                          "marks": [
                            {
                              "type": "strong"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": "Given a guest shopper"
                        },
                        {
                          "type": "text",
                          "text": " ",
                          "marks": [
                            {
                              "type": "textColor",
                              "attrs": {
                                "color": "#ff5630"
                              }
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": "browses products within a session, when they navigate to a page with the Recently Viewed rail, then products viewed during that session are shown. When the browser session ends, the history is cleared."
                        }
                      ],
                      "attrs": {
                        "localId": "e819a11dd6e2"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "e200a12cd252"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Authenticated Shopper: ",
                          "marks": [
                            {
                              "type": "strong"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": "Given an authenticated shopper has previously viewed products, when they log in on any device, then their Recently Viewed history is restored and displayed in the rail."
                        }
                      ],
                      "attrs": {
                        "localId": "5d36057e1f03"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "a72cdf09d50f"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Empty state: ",
                          "marks": [
                            {
                              "type": "strong"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": "Given a shopper has not viewed any products in their current session (and is not authenticated with any history), then the Recently Viewed component is not rendered on the page — no empty rail or placeholder is shown."
                        }
                      ],
                      "attrs": {
                        "localId": "4c618ac990fd"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "bbd04a6bd388"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Cross-page consistency: ",
                          "marks": [
                            {
                              "type": "strong"
                            }
                          ]
                        },
                        {
                          "type": "text",
                          "text": "Given the Recently Viewed component is embedded on PLP, PDP and anywhere else, then the same browsing history and tile design is shown consistently across all surfaces."
                        }
                      ],
                      "attrs": {
                        "localId": "c47200f67362"
                      }
                    }
                  ]
                }
              ]
            }
          ]
        }
