                  "text": "Shopper",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "c1d0fee28145"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "4b84d72dc399"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f33711c26380"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper visits any page on the storefront, when the page loads, then the global footer is displayed at the bottom of the page on both desktop and mobile."
                        }
                      ],
                      "attrs": {
                        "localId": "c1d0fee28145"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "91f38a23da69"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper views the footer on desktop, when the page loads, then navigation links are displayed in columns (ABOUT, CONTACT, HELP) per the Figma design."
                        }
                      ],
                      "attrs": {
                        "localId": "c76cfe623df6"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "91f38a23da69"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper hovers over one of the navigation links, the rollover state will be that that word or those words are underlined."
                        }
                      ],
                      "attrs": {
                        "localId": "eb54cec91ac9"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "ca776220e519"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper views the footer on mobile, when the page loads, then navigation columns stack vertically per the Figma design."
                        }
                      ],
                      "attrs": {
                        "localId": "bd567249d3ac"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "ab3b9a32e736"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper views the footer, when the page loads, then the Stay in Touch section is displayed with an email input field and submit button as a placeholder component."
                        }
                      ],
                      "attrs": {
                        "localId": "ad4a8c6dcd5a"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "4065e5cf3e44"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper views the footer, when the page loads, then the Zimmermann wordmark, region/currency indicator, copyright text, and legal links are displayed in the bottom bar per the Figma design."
                        }
                      ],
                      "attrs": {
                        "localId": "eb1267301c42"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Site Merchandiser",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "5e1e3e2b02f4"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "39da4004bbc1"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "ea66baa323b2"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a storefront needs particular links to be included in the footer, when the merchandiser is setting up the storefront in SFCC, then they are able to define the links in the footer per storefront."
                        }
                      ],
                      "attrs": {
                        "localId": "b188fd6e0c1d"
                      }
                    }
                  ]
                }
              ]
            }
          ]
        }
