      "customfield_10231": {
        "value": {
          "type": "doc",
          "version": 1,
          "content": [
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Desktop/Mobile:",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "f0301d883a5c"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 1,
                "localId": "c4c38fe14026"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "67c8f745055e"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper visits any page on the storefront, when the page loads, then the global header is displayed at the top of the page on both desktop and mobile."
                        }
                      ],
                      "attrs": {
                        "localId": "d440d7129833"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "b59428cb57b6"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper scrolls down the page, when the page is scrolled, then the top navigation remains sticky and visible at the top of the screen."
                        }
                      ],
                      "attrs": {
                        "localId": "016bdf5b58fc"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "8b59ad8682bf"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper clicks the Zimmermann logo, when the click is registered, then the shopper is navigated to the homepage."
                        }
                      ],
                      "attrs": {
                        "localId": "e356d4fd0312"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "685aa225f5f4"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper has items in their bag, when they view the header, then the Bag icon displays the correct running count of items."
                        }
                      ],
                      "attrs": {
                        "localId": "b89ee6f6da0d"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "dbf5ad31ee7f"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a bag item is added or removed, when the bag is updated, then the Bag icon count updates without requiring a full page reload."
                        }
                      ],
                      "attrs": {
                        "localId": "e6a0cdb3fa0d"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Desktop:",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "b62630d13c72"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 6,
                "localId": "e88129925ad5"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "ec811ba3cee6"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper views the header, when the page loads, then all header icons (Search, Account, Saved, Bag) are visible per the linked Figma Design."
                        }
                      ],
                      "attrs": {
                        "localId": "8f0129bae4a8"
                      }
                    }
                  ]
                }
              ]
            },
            {
              "type": "paragraph",
              "content": [
                {
                  "type": "text",
                  "text": "Mobile:",
                  "marks": [
                    {
                      "type": "strong"
                    }
                  ]
                }
              ],
              "attrs": {
                "localId": "79ba43876d87"
              }
            },
            {
              "type": "orderedList",
              "attrs": {
                "order": 7,
                "localId": "8e58e98bfe02"
              },
              "content": [
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "b911d8760add"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper views the site on mobile, when any page loads, then the hamburger icon is displayed top-left in the header alongside Search and Bag icons top-right."
                        }
                      ],
                      "attrs": {
                        "localId": "809c470746b2"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "349b2bae3c5b"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given a shopper taps the hamburger icon, when the tap is registered, then the full-screen navigation drawer opens and the hamburger icon is replaced by a close (×) icon."
                        }
                      ],
                      "attrs": {
                        "localId": "351aaf2b529c"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f3b5c1709081"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the navigation drawer is open, when a shopper taps the close (×) icon, then the drawer closes and the hamburger icon is restored."
                        }
                      ],
                      "attrs": {
                        "localId": "cd29f383fdde"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "64f2a0369f71"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the navigation drawer is open, when a shopper views it, then all top-level navigation categories are displayed vertically in the correct order per the linked Figma design."
                        }
                      ],
                      "attrs": {
                        "localId": "776c36eaf746"
                      }
                    }
                  ]
                },
                {
                  "type": "listItem",
                  "attrs": {
                    "localId": "f1b052fec3c7"
                  },
                  "content": [
                    {
                      "type": "paragraph",
                      "content": [
                        {
                          "type": "text",
                          "text": "Given the navigation drawer is open, when a shopper views it, then Saved and Account links are displayed below the main navigation categories."
                        }
                      ],
                      "attrs": {
                        "localId": "374966240830"
                      }
                    }
                  ]
                }
              ]
            }
          ]
        }
